use genex::prelude::*;

/// The gun's parts in its own space (metres): slide, frame, barrel, grip, sights. A pistol is ~0.19 m long.
const PARTS: [(Vec3, Vec3); 4] = [
    (Vec3::new(0.0, 0.035, -0.06), Vec3::new(0.03, 0.03, 0.19)),  // slide
    (Vec3::new(0.0, 0.012, -0.05), Vec3::new(0.028, 0.02, 0.16)), // frame and dust cover
    (Vec3::new(0.0, -0.045, 0.01), Vec3::new(0.026, 0.09, 0.035)), // grip, turned back below
    (Vec3::new(0.0, 0.054, -0.13), Vec3::new(0.006, 0.008, 0.006)), // front sight
];
const GRIP_RAKE: f32 = 0.26; // radians the grip leans back

fn draw_gun(frame: &mut Frame, pose: Transform, slide: &Material, polymer: &Material) {
    frame.tag("weapon");
    for (i, (at, size)) in PARTS.iter().enumerate() {
        let lean = if i == 2 { Quat::from_rotation_x(GRIP_RAKE) } else { Quat::IDENTITY };
        let local = Transform::from_translation(pose.translation + pose.rotation * *at)
            .with_rotation(pose.rotation * lean)
            .with_scale(*size);
        frame.cube_with(local, if i == 0 { slide } else { polymer });
    }
    // The barrel's end shows as a round bore, not a box face.
    frame.sphere_with(pose.translation + pose.rotation * vec3(0.0, 0.035, -0.155), 0.007, polymer);
}
